		$old_data = array_map('makeSafe', $old_data);
		$old_data['selectedID'] = makeSafe($selected_id);
	}

	$data['selectedID'] = makeSafe($selected_id);

	// hook: employees_appraisal_table_before_update
	if(function_exists('employees_appraisal_table_before_update')) {
		$args = ['old_data' => $old_data];
		if(!employees_appraisal_table_before_update($data, getMemberInfo(), $args)) {
			if(isset($args['error_message'])) $error_message = $args['error_message'];
			return false;
		}
	}

	$set = $data; unset($set['selectedID']);
	foreach ($set as $field => $value) {
		$set[$field] = ($value !== '' && $value !== NULL) ? $value : NULL;
	}

	if(!update(
		'employees_appraisal_table', 
		backtick_keys_once($set), 
		['`id`' => $selected_id], 
		$error_message
	)) {
		echo $error_message;
		echo '<a href="employees_appraisal_table_view.php?SelectedID=' . urlencode($selected_id) . "\">{$Translation['< back']}</a>";
		exit;
	}


	update_calc_fields('employees_appraisal_table', $data['selectedID'], calculated_fields()['employees_appraisal_table']);

	// hook: employees_appraisal_table_after_update
	if(function_exists('employees_appraisal_table_after_update')) {
		if($row = getRecord('employees_appraisal_table', $data['selectedID'])) $data = array_map('makeSafe', $row);

		$data['selectedID'] = $data['id'];
		$args = ['old_data' => $old_data];
		if(!employees_appraisal_table_after_update($data, getMemberInfo(), $args)) return;
	}

	// mm: update record update timestamp
	set_record_owner('employees_appraisal_table', $selected_id);
}

