	$filterValue = Request::val('FilterValue');
	if(isset($filterField[1]) && $filterField[1] == '3' && $filterOperator[1] == '<=>')
		$templateCode.="\n<input type=hidden name=employee_designation_lookup value=\"" . html_attr($filterValue[1]) . "\">\n";

	// don't include blank images in lightbox gallery
	$templateCode = preg_replace('/blank.gif" data-lightbox=".*?"/', 'blank.gif"', $templateCode);

	// don't display empty email links
	$templateCode=preg_replace('/<a .*?href="mailto:".*?<\/a>/', '', $templateCode);

	/* default field values */
	$rdata = $jdata = get_defaults('employees_appraisal_table');
	if($hasSelectedId) {
		$jdata = get_joined_record('employees_appraisal_table', $selectedId);
		if($jdata === false) $jdata = get_defaults('employees_appraisal_table');
		$rdata = $row;
	}
	$templateCode .= loadView('employees_appraisal_table-ajax-cache', ['rdata' => $rdata, 'jdata' => $jdata]);

	// hook: employees_appraisal_table_dv
	if(function_exists('employees_appraisal_table_dv')) {
		$args = [];
		employees_appraisal_table_dv(($hasSelectedId ? $selectedId : FALSE), getMemberInfo(), $templateCode, $args);
	}

	return $templateCode;
}